from collections import deque

def bfs(graphe, depart, but):
    if depart == but:
        return [depart]
    file = deque([depart])
    parent = {depart: None}
    while file:
        s = file.popleft()
        for v in graphe.get(s, []):
            if v in parent:
                continue
            parent[v] = s
            if v == but:
                chemin = [v]
                while chemin[-1] is not None:
                    chemin.append(parent[chemin[-1]])
                return chemin[-2::-1]
            file.append(v)
    return None

testcode.text:
G = {i: [i + 1] for i in range(50)}
G[50] = []
print(len(bfs(G, 0, 50)))

