import heapq

def cout_uniforme(graphe, depart, but):
    g = {depart: 0}
    parent = {depart: None}
    tas = [(0, depart)]
    ferme = set()
    while tas:
        cout, s = heapq.heappop(tas)
        if s in ferme:
            continue
        ferme.add(s)
        if s == but:
            chemin = []
            while s is not None:
                chemin.append(s)
                s = parent[s]
            return (cout, chemin[::-1])
        for v, c in graphe.get(s, []):
            if v not in g or cout + c < g[v]:
                g[v] = cout + c
                parent[v] = s
                heapq.heappush(tas, (cout + c, v))
    return (float('inf'), None)

import heapq

def a_star(grille, depart, arrivee):
    nl, nc = len(grille), len(grille[0])

    def libre(p):
        i, j = p
        return 0 <= i < nl and 0 <= j < nc and grille[i][j] != '#'

    def h(p):
        return abs(p[0] - arrivee[0]) + abs(p[1] - arrivee[1])

    if not libre(depart) or not libre(arrivee):
        return (-1, 0)
    g = {depart: 0}
    tas = [(h(depart), 0, depart)]
    ferme = set()
    developpes = 0
    while tas:
        f, mg, p = heapq.heappop(tas)
        if p in ferme:
            continue
        ferme.add(p)
        developpes += 1
        if p == arrivee:
            return (-mg, developpes)
        i, j = p
        for v in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
            if not libre(v):
                continue
            ng = g[p] + 1
            if v not in g or ng < g[v]:
                g[v] = ng
                heapq.heappush(tas, (ng + h(v), -ng, v))
    return (-1, developpes)

import heapq

def diagnostic(graphe, h, but):
    # distances reelles vers le but : Dijkstra sur le graphe inverse
    inverse = {s: [] for s in graphe}
    for u in graphe:
        for v, c in graphe[u]:
            inverse.setdefault(v, []).append((u, c))
            inverse.setdefault(u, inverse.get(u, []))
    d = {but: 0}
    tas = [(0, but)]
    while tas:
        cout, s = heapq.heappop(tas)
        if cout > d.get(s, float('inf')):
            continue
        for u, c in inverse.get(s, []):
            if cout + c < d.get(u, float('inf')):
                d[u] = cout + c
                heapq.heappush(tas, (cout + c, u))
    admissible = all(h[s] <= d[s] for s in graphe if s in d and s in h)
    coherente = h.get(but, 0) == 0
    for u in graphe:
        for v, c in graphe[u]:
            if u in h and v in h and h[u] > c + h[v]:
                coherente = False
    return (admissible, coherente)

def ida_star(graphe, h, depart, but):
    borne = h.get(depart, 0)
    chemin = [depart]

    def explorer(g, borne):
        s = chemin[-1]
        f = g + h.get(s, 0)
        if f > borne:
            return f
        if s == but:
            return 'TROUVE'
        mini = float('inf')
        for v, c in graphe.get(s, []):
            if v in chemin:
                continue
            chemin.append(v)
            r = explorer(g + c, borne)
            chemin.pop()
            if r == 'TROUVE':
                return 'TROUVE'
            if r < mini:
                mini = r
        return mini

    while True:
        r = explorer(0, borne)
        if r == 'TROUVE':
            return borne
        if r == float('inf'):
            return -1
        borne = r
